float noise(vec2 uv,float mip){
return texture(iChannel0,uv,mip).r;
}
float height(vec2 uv,float zoom){
float scal=0.1;
float ou=0.0;
for(int i=0;i<int(log(1.0/zoom)*2.8);i++){
scal*=2.1;
ou+=((noise(uv*scal,zoom)-0.5)*exp(zoom))/(scal*0.01+0.99)*log(1.0/zoom);
}

return ou*2.0;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
float zoom=exp2(((iMouse.x/iResolution.x)*1524.0+750.0)/140.0);
float mi=3.0/min(zoom,1200.0);
float mid=height((uv-0.5)/zoom+0.5,mi);
float dx=height((uv-0.5)/zoom+0.5+vec2(0.000001,0.0),mi);
float dy=height((uv-0.5)/zoom+0.5+vec2(0.0,0.000001),mi);
vec2 grad=vec2(mid-dx,mid-dy);
vec3 norm=vec3(grad,1.0);
norm=normalize(norm);
float light=max(dot(normalize(vec3(1.0,1.0,2.0)),normalize(norm)),mid/25.0+0.1);
float samp=mid/1.0;
   fragColor.rgb=(texture(iChannel1,vec2(samp/40.0,samp/40.0)).rgb*1.25+0.15+mid*0.05)*light;
   light*=light;
   light*=light;
   light*=light;
uv=((uv-0.5)/(zoom*0.0001))+0.5;
   fragColor.rgb+=(light)/log(zoom);
   if(texture(iChannel2,uv+vec2(mid)/500.0).a>0.0){
   fragColor.rgb/=3.0;
   }
   vec4 shad=texture(iChannel2,uv);
   if(shad.a>0.5){
   fragColor.rgb=shad.rgb;
   }

  // fragColor.rgb=norm;
    fragColor.a=1.0;
}

